            function UlozDetailBaliku(input) {
                return Gordic.Prefabs.Actions.buildActionPrefab(input, Gordic.Prefabs.Icons.IconToActionParams(Gordic.Prefabs.Icons.Ulozit()), {
                    name: Names.UlozDetailBaliku,
                    run: (ev, ctx) => {
                        ctx.content.beginOperation("jres:32130062"); //RC 32130062 : Ukládám data.
                        let promise;
                        if (ctx.inputData.isNew) {
                            // 13.10.2020 - TFeik
                            // Rozšíření o příznak IsRezimSpisovna.
                            promise = Gordic.Isl.Balik.create({
                                Balik: ctx.inputData.data,
                                IsRezimSpisovna: ctx.inputData.isRezimSpisovna,
                                ReadRequest: ctx.inputData.isRezimSpisovna != null ? {
                                    IsRezimSpisovna: ctx.inputData.isRezimSpisovna
                                } : undefined
                            }).getData();
                        }
                        else {
                            promise = Gordic.Isl.Balik.update({
                                Balik: ctx.inputData.data,
                                ReadRequest: ctx.inputData.isRezimSpisovna != null ? {
                                    IsRezimSpisovna: ctx.inputData.isRezimSpisovna
                                } : undefined
                            }).getData();
                        }
                        //return WebClient.GDetailBalikuHandler.SaveDetailBaliku(ctx.inputData.data, ctx.inputData.isNew)
                        return promise
                            .then((retVal) => {
                            return retVal?.Balik;
                        })
                            .always((retVal) => {
                            //Gin.WebClient.GGinUtils.showBaseReturnDtoMessages(ctx.content, retVal);
                            ctx.content.endOperation();
                        });
                    }
                });
            }
