            function NeevidovanyDokumentSpisSave(input) {
                return Gordic.Prefabs.Actions.buildActionPrefab(input, Gordic.Prefabs.Icons.IconToActionParams(Gordic.Prefabs.Icons.Ulozit()), {
                    name: Names.NeevidovanyDokumentSpisSave,
                    run: function (ev, ctx) {
                        ctx.content.beginOperation("jres:32130095"); //RC 32130095 : Ukládám neevidovaný dokument / spis.
                        let promise = undefined;
                        // 01.10.2019 - TFeik
                        // Volání ISL metody změněno tak, že jsou hodnoti vstupního Dto v propertty data, 
                        // jinak způsobovalo problémy při volání s NullPointerException.
                        if (ctx.inputData.action === "createNew") {
                            promise = Gordic.Isl.PisemnostNeevidovana.create({ data: ctx.inputData.data }).get();
                        }
                        else if (ctx.inputData.action === "opravitPoKontroleMetadat") {
                            promise = Gordic.Isl.PisemnostNeevidovana.opravitPoKontroleMetadat({ data: ctx.inputData.data }).get();
                        }
                        else {
                            promise = Gordic.Isl.PisemnostNeevidovana.update({ data: ctx.inputData.data }).get();
                        }
                        return promise
                            .done(function () {
                            ctx.showFlash("jres:32130096", "success"); //RC 32130096 : Neevidovaný dokument / spis je úspěšně uložen.
                        })
                            .fail(function () {
                            ctx.showFlash("jres:32130097", "error"); //RC 32130097 : Během ukládání neevidovaného dokumentu / spisu došlo k chybě.
                        })
                            .always(function () {
                            ctx.content.endOperation();
                        });
                    }
                });
            }
