            function SekceFormaFilter(opt) {
                const fieldAnalogOptions = {
                    name: "analog",
                    label: "jres:26286123" //RC 26286123 : Analogové (fyzické)
                };
                const fieldHybridAnalogOptions = {
                    name: "hybridAnalog",
                    label: "jres:26286124" //RC 26286124 : Hybridní analogové
                };
                const fieldHybridDigitalOptions = {
                    name: "hybridDigital",
                    label: "jres:26286125" //RC 26286125 : Hybridní digitální
                };
                const fieldDigitalOptions = {
                    name: "digital",
                    label: "jres:26286126" //RC 26286126 : Digitální
                };
                var data = [
                    { id: fieldAnalogOptions.name, label: fieldAnalogOptions.label },
                    { id: fieldHybridAnalogOptions.name, label: fieldHybridAnalogOptions.label },
                    { id: fieldHybridDigitalOptions.name, label: fieldHybridDigitalOptions.label },
                    { id: fieldDigitalOptions.name, label: fieldDigitalOptions.label },
                ];
                var initialValueData = [];
                if (opt.value.analog)
                    initialValueData.push({ id: fieldAnalogOptions.name });
                if (opt.value.hybridAnalog)
                    initialValueData.push({ id: fieldHybridAnalogOptions.name });
                if (opt.value.hybridDigital)
                    initialValueData.push({ id: fieldHybridDigitalOptions.name });
                if (opt.value.digital)
                    initialValueData.push({ id: fieldDigitalOptions.name });
                const formPrefabSelect = new Gordic.Forms.Form({ name: "FiltrFormarPrefabForm" })
                    .addSection()
                    .addRow({ label: "", name: "FormaFiltrRow", favoriteRowLayoutDescriptor: "w-L-6 w-M-8 w-S-12" })
                    .addField("gselectbox", {
                    name: "FormaFiltr",
                    multi: true,
                    list: true,
                    initialValue: initialValueData,
                    //verticalButtons: true,
                    itemTemplate: "{label}",
                    itemWidth: "w-3",
                    data: new Gordic.Data.View(data, { key: "id" }),
                    model: function (operation, dtoFinal, modelOptions) {
                        dtoFinal = dtoFinal ? dtoFinal : {};
                        if (dtoFinal.Forma == null)
                            dtoFinal.Forma = {};
                        var dto = dtoFinal.Forma;
                        switch (operation) {
                            case "apply": // naplneni multivalue policka z DTO
                                var val = [];
                                if (dto[fieldAnalogOptions.name]) {
                                    val.push({ id: fieldAnalogOptions.name });
                                }
                                if (dto[fieldHybridAnalogOptions.name]) {
                                    val.push({ id: fieldHybridAnalogOptions.name });
                                }
                                if (dto[fieldHybridDigitalOptions.name]) {
                                    val.push({ id: fieldHybridDigitalOptions.name });
                                }
                                if (dto[fieldDigitalOptions.name]) {
                                    val.push({ id: fieldDigitalOptions.name });
                                }
                                $(this).gfield("setValue", val, { valid: false });
                                return;
                            case "collect":
                                var value = $(this).gfield("getValue");
                                dto[fieldAnalogOptions.name] = false;
                                dto[fieldHybridAnalogOptions.name] = false;
                                dto[fieldHybridDigitalOptions.name] = false;
                                dto[fieldDigitalOptions.name] = false;
                                if (value) {
                                    for (var i = 0; i < value.length; i++) {
                                        switch (value[i].id) {
                                            case fieldAnalogOptions.name:
                                                dto[fieldAnalogOptions.name] = true;
                                                break;
                                            case fieldHybridAnalogOptions.name:
                                                dto[fieldHybridAnalogOptions.name] = true;
                                                break;
                                            case fieldHybridDigitalOptions.name:
                                                dto[fieldHybridDigitalOptions.name] = true;
                                                break;
                                            case fieldDigitalOptions.name:
                                                dto[fieldDigitalOptions.name] = true;
                                                break;
                                        }
                                    }
                                }
                                return;
                        }
                        return "FormaFiltr";
                    }
                });
                return formPrefabSelect.form.sections[0].rows;
            }
