                            if (vlozitParovyDokument == null) {
                                return $.Deferred()
                                    .reject(callInputDto)
                                    .promise();
                            }
                            if (input?.zapamatovatVolbu) {
                                GDetailBalikuHandler.VlozitDokumentSpisDoBalikuVlozitParovyDokumentTemp = vlozitParovyDokument;
                            }
                            return setVlozitParovyDokument(vlozitParovyDokument);
