                                //    flashOptions.state = "success";
                                //} else {
                                //    flashOptions.label = "Zkontrolováno {0} z {1} položek.".format(countOfChecked, pisemnosti.length);
                                //    flashOptions.state = "info";
                                //    // 05.12.2019 - TFeik
                                //    // Pokud nejsou zkontrolované všechny položky tak vrátím focus na políčko s pidem, 
                                //    // aby mohl uživatel rozvnou zadávat další identifikátor.
                                //    // Zpoždění je nastaveno proto, aby byl focus nastaven až potom, co je automaticky posunut na další položku.
                                //    $("input", $ixpField).focus(10);
