                //#region Akce
                static _createActions(content, componentDto) {
                    const result = [];
                    result.push($.extend(Gordic.Prefabs.Icons.IconToActionParams(Gordic.Gin.Globals.Icons.Editovat()), {
                        name: ActionNames.editovat,
                        run: function () {
                            content.zmenaEditace(componentDto);
                        }
                    }));
                    result.push(Spi.PreActions.NeevidovanyDokumentSpisSave({
                        inputData: function () {
                            return content.getDataNeevidovanyDokumentSpis(componentDto)
                                .then(function (data) {
                                if (!data) {
                                    return $.Deferred().reject().promise();
                                }
                                return $.Deferred().resolve({
                                    data: data,
                                    action: componentDto.TypZobrazeniDetailu === 1 /* Gin.Interface.TypZobrazeniEntity.New */ ? "createNew"
                                        : componentDto.OpravaNevalidnihoPoKontroleMetadat ? "opravitPoKontroleMetadat"
                                            : "update"
                                }).promise();
                            });
                        },
                        done: function (retVal) {
                            if (componentDto.TypZobrazeniDetailu === 4 /* Gin.Interface.TypZobrazeniEntity.Edit */
                            /*|| componentDto.TypZobrazeniDetailu === Wfl.Client.TypZobrazeniDetailuObecneho.New*/ ) {
                                content.zmenaEditace(componentDto, true);
                            }
                            else if (componentDto.TypZobrazeniDetailu === 1 /* Gin.Interface.TypZobrazeniEntity.New */) {
                                content.WasSaved = true;
                                content.tryClose();
                            }
                            else {
                                content.reload(componentDto, true);
                            }
                        }
                    }));
                    result.push(Gordic.Prefabs.Actions.ZavritContent());
                    return result;
                }
                static _createMenuBar() {
                    const observableDokumentMenuParam = new GObservableObject($.extend(Gordic.Prefabs.Icons.IconToMenuParams(Gordic.Gin.Globals.Icons.NeevidovanyDokumentSpis()), {
                        id: parentMenuId.dokumnetSpis,
                        type: "static",
                        favorite: true
                    }));
                    return {
                        observableDokumentMenuParam: observableDokumentMenuParam,
                        menu: [
                            observableDokumentMenuParam,
                            {
                                parent: parentMenuId.dokumnetSpis,
                                action: ActionNames.editovat,
                                favorite: true
                            },
                            {
                                parent: parentMenuId.dokumnetSpis,
                                action: Spi.PreActions.Names.NeevidovanyDokumentSpisSave,
                                favorite: true
                            }
                        ]
                    };
                }
                static _createCommandBar() {
                    return [
                        {
                            action: Spi.PreActions.Names.NeevidovanyDokumentSpisSave,
                            primary: true
                        },
                        {
                            action: Gordic.Prefabs.Actions.Names.ZavritContent
                        }
                    ];
                }
                static UpdateDokumentSpisAction(observableDokumentMenuParam, prizSpis) {
                    if (observableDokumentMenuParam) {
                        const icon = prizSpis == undefined ? Gordic.Gin.Globals.Icons.NeevidovanyDokumentSpis()
                            : prizSpis == 1 ? Gordic.Gin.Globals.Icons.NeevidovanySpis() : Gordic.Gin.Globals.Icons.NeevidovanyDokument();
                        observableDokumentMenuParam.update(Gordic.Prefabs.Icons.IconToMenuParams(icon));
                    }
                }
