                PrevzitAsync(Selected) {
                    let that = this;
                    //const op = this.beginOperation({
                    //    id: "GServerAsyncTask",
                    //    cancelAction: new GAction({ name: "cancelAct", caption: "Storno", run: () => { pTask.cancel() } }),
                    //    progress: 1,
                    //    total: 100,
                    //    text: "GServerAsyncTask nastartovano"
                    //})
                    const op = this.beginOperation({
                        id: "GServerAsyncTask",
                        text: "jres:23900031" //RC 23900031 : Probíhá převzetí
                    });
                    var l_imput = {};
                    l_imput.Selected = Selected;
                    l_imput.IxsBaliku = this.model.IxsBaliku;
                    l_imput.IxsFunPredavajici = this.model.IxsFunPredavajici;
                    l_imput.IxsSuPredavajici = this.model.IxsSuPredavajici;
                    l_imput.Uzavrit = this.model.Uzavrit;
                    l_imput.TypPrevzeti = this.model.TypPrevzeti;
                    l_imput.logPorCislo = this.SessionInfo.LogPorCislo;
                    this.beginOperation();
                    const pTask = Gordic.Async.GTaskManager.start("Gordic.Spi.Server.GSpiServerPrevzetiDokSpisAsyncTask", l_imput);
                    pTask.getPromise()
                        .then(
                    //Uspech
                    (ctx) => {
                        const result = ctx.result;
                        if (result.Info && result.Info != "")
                            that.Info = result.Info;
                        if (result.ErrorText && result.ErrorText != "")
                            that.Info += result.ErrorText;
                        that.ResultType = result.Vysledek;
                        that.endOperation();
                        if (result.Vysledek == 2 /* Gin.Interface.TypVysledkuOperace.Provedeno */) {
                            Gordic.Gin.Globals.ShowWaitDoAkce(this);
                            that.call("AfterPrevzeti", { model: this.model })
                                .done(function (data) {
                                that.endOperation();
                                Gordic.Wfl.ListAC.WflListBaseAC.ResolveResultData(that, data);
                                var l_resultInfo = Gordic.Wfl.ListAC.WflListBaseAC.GetResultInfoByData(that, that.IDPrimaryKeyGridu);
                                if (Gordic.Wfl.Common.GetPocetDleTypVysledkuOperace(l_resultInfo, 2 /* Gordic.Gin.Interface.TypVysledkuOperace.Provedeno */) > 0) {
                                    if (that.IfTiskPredavacihoProtokoluVRamciSU || that.SessionInfo.IxsSu != that.IxsSuOperation)
                                        Lists.SpiListBaseAC.TiskPredavacihoProtokolu(that, false, that.SpiListContext.IxsSpiAktualni);
                                }
                                else
                                    Gordic.Wfl.ListAC.WflListBaseAC.ShowGlobalInfo(that);
                            })
                                .always(function () {
                                that.endOperation();
                            });
                        }
                        else {
                            that.endOperation();
                            Gordic.Wfl.AC.WflBaseAC.ResolveInfo(that);
                        }
                    }, 
                    //Neuspech
                    (ctx) => {
                        const exc = ctx.exception;
                        if (ctx.state === 6 /* Gordic.Async.GTaskState.cancelSignalized */)
                            this.dialogs.alert("Stornovano");
                        else if (ctx.state === 4 /* Gordic.Async.GTaskState.faulted */ && ctx.handled !== true) {
                            this.dialogs.showException(exc);
                            ctx.handled = true;
                        }
                        return $.Deferred().reject().promise();
                    }, 
                    //Progress
                    (ctx) => {
                        const p = ctx.progress;
                        if (p) {
                            op.progress = p.current;
                            op.total = p.total;
                            op.text = p.text;
                            this.progressOperation(op);
                        }
                    })
                        .always(() => { pTask.clean(); this.endOperation(op); });
                }
