                CreateGridFormat() {
                    let that = this;
                    var OpenDetail = new GAction({
                        name: "gridRowSelectedAct",
                        run: function (ev, ctx) {
                            var rowData = ctx.cellInfo.data; //data, ze kterych byl vytvoren radek
                            Spi.Dialogs.GDetailUloznehoMistaDlg(that, { ixs_ulm: rowData.ixs_ulm });
                        }
                    });
                    var gf = Gordic.Wfl.ListAC.WflListBaseAC.GetGridFormat();
                    gf.addTextColumn(Spi.Prefabs.ixsUlmColumn());
                    gf.addTextColumn(Spi.Prefabs.popisColumn());
                    gf.addTextColumn(Spi.Prefabs.ixsUlmNadColumn());
                    gf.addTextColumn(Spi.Prefabs.budovaSegmentMistnostAddColumn());
                    gf.add(Spi.Prefabs.paprsekColumn());
                    gf.add(Spi.Prefabs.policeColumn());
                    gf.addDateTimeColumn(Gordic.Wfl.ListPrefabs.datDatZmenaColumn());
                    gf.addTextColumn(Spi.Prefabs.nazevZmenuProvAddColumn());
                    this.gridFormat = gf;
                    this.gridDefaultAction = OpenDetail;
                    this.gridOptions.rowsClass = function (dataRow) {
                        var l_ret = "  ";
                        if (dataRow && dataRow.data) {
                            var l_textState = "g-state-text ";
                            switch (dataRow.data.aktivita) {
                                case 100:
                                    break;
                                default:
                                    l_ret = l_textState + Gordic.Global.Enums.ColorStateClass.inactive;
                                    break;
                            }
                        }
                        return l_ret;
                    };
                    this.mainGrid = Gordic.Wfl.ListAC.WflListBaseAC.CreateGridBase(this, gf);
                }
