                LoadDataListULM() {
                    if (this.Vyber == false) {
                        let that = this;
                        Gordic.Gin.Globals.ShowWaitLoadData(this);
                        if (this.model) {
                            this.call("LoadDataUloznaMista", { model: this.model })
                                .done(function (data) {
                                var view = new Gordic.Data.View(data, { key: that.IDPrimaryKeyGridu }); //key je dulezity kvuli pripadnemu vyhledavani radku
                                Gordic.Wfl.ListAC.WflListBaseAC.ResolveResultData(that, data);
                            })
                                .always(function () {
                                Gordic.Wfl.ListAC.WflListBaseAC.AfterLoadData(that);
                            });
                        }
                    }
                }
                LoadDataStromu(refresh) {
                    let that = this;
                    Gordic.Gin.Globals.ShowWaitLoadData(this);
                    var l_aktRow = this.gridStrom.ggrid("activeRow");
                    if (this.model) {
                        this.call("LoadDataStromu", { model: this.model })
                            .done(function (data) {
                            that.stromList = data;
                            that.NaplnStromGrid(refresh);
                        })
                            .always(function () {
                            Gordic.Wfl.ListAC.WflListBaseAC.AfterLoadData(that);
                            debugger;
                            if (refresh && l_aktRow) {
                                that.gridStrom.ggrid("activeRow", l_aktRow);
                            }
                        });
                    }
                }
