                /**
                 * Prefab políčka Ixs balíku.
                 *
                 * @author  TFeik
                 * @date    11.12.2018
                 * @see [xWiki]{@link }
                 *
                 * @param {GSelectBoxOptions<Gordic.Data.Readers.WflcsdoDto>} [fieldOpt] Options políčka.
                 * @param {GFormRowOptions} [rowOpt] Options řádku.
                 * @returns {Gordic.Forms.FormRow[]} Řádky prefabu.
                 */
                function GIxsBaliku(opt, rowOpt, mergeButtons, others) {
                    if (!opt) {
                        opt = {};
                    }
                    let buttons = undefined;
                    if (mergeButtons !== false) {
                        buttons = [];
                        if (others?.showActionGenerujPid !== false) {
                            const generujIcon = Gordic.Gin.Globals.Icons.GenerovaniIdentifikatoru();
                            buttons.push({
                                icon: generujIcon.icon,
                                action: new GAction({
                                    name: 'actDetailBalikuHeaderGenerujPid',
                                    tooltip: generujIcon.tooltip, //"jres:32130075", //RC 32130075 : Generuj PID
                                    run: function (event, data) {
                                        const $gfield = $(event.target).closest(".gfield");
                                        Gordic.Isl.Balik.generateIxsZup().get()
                                            .done(function (retVal) {
                                            if (retVal && retVal.result && retVal.result.data && retVal.result.data.ixs_zup) {
                                                Gordic.Wfl.Prefabs._setFieldValueInternal($gfield, retVal.result.data.ixs_zup);
                                            }
                                        });
                                    }
                                })
                            });
                        }
                        if (others?.showActionOpenDetail) {
                            buttons.push({
                                requireValue: true,
                                requireEdit: false,
                                caption: '',
                                action: new GAction(Spi.PreActions.OtevriDetailBaliku({
                                    inputData: (action, event, ctx, param) => {
                                        const deferred = $.Deferred();
                                        const $gfield = $(event?.target).closest(".gfield");
                                        const ixp = Gordic.Utils.WidgetExists('gfield', $gfield)
                                            ? $gfield.gfield('getValue')?.trim()
                                            : void 0;
                                        if (ixp) {
                                            deferred.resolve({
                                                parentContent: $.content($gfield),
                                                opt: {
                                                    IxsZup: ixp
                                                }
                                            });
                                        }
                                        else {
                                            deferred.reject();
                                        }
                                        return deferred.promise();
                                    }
                                }))
                            });
                        }
                        if (opt?.fieldOpt?.buttons) {
                            buttons = $.merge(buttons, opt.fieldOpt.buttons);
                            opt.fieldOpt.buttons = undefined;
                        }
                    }
                    const fieldOptions = $.extend(true, {
                        name: Names.ixsBaliku,
                        buttons: buttons
                    }, opt.fieldOpt);
                    const rowOptions = {
                        label: "jres:26285045" //RC 26285045 : PID balíku
                    };
                    return Gordic.Gin.Prefabs.GIdentifikator($.extend(true, {
                        isPid: false,
                        fieldOpt: fieldOptions
                    }, opt), $.extend(true, rowOptions, rowOpt), mergeButtons);
                }
                Row.GIxsBaliku = GIxsBaliku;
