                    pocetJednotekFieldOpt = Gordic.Gin.Prefabs.checkFieldOpt(pocetJednotekFieldOpt);
                    pocetListuFieldOpt = Gordic.Gin.Prefabs.checkFieldOpt(pocetListuFieldOpt);
                    rowOpt = Gordic.Gin.Prefabs.checkRowOpt(rowOpt);
                    const pocetDokumentuFieldOptions = {
                        name: pocetDokumentuFieldOpt.name ? pocetDokumentuFieldOpt.name : Names.pocetDokumentu
                    };
                    const pocetJednotekFieldOptions = {
                        name: pocetJednotekFieldOpt.name ? pocetJednotekFieldOpt.name : Names.pocetJednotek
                    };
                    const pocetListuFieldOptions = {
                        name: pocetListuFieldOpt.name ? pocetListuFieldOpt.name : Names.pocetListu
                    };
                    const rowOptions = {
                        label: rowOpt.label ? rowOpt.label : "jres:32130076" //RC 32130076 : Počet dokumentů, jednotek, listů
                    };
                    return Gordic.Gin.Prefabs.preReturn(new Gordic.Forms
                        .Form({ name: tempFormName })
                        .addSection()
                        .addRow($.extend(true, rowOpt, rowOptions))
                        .addField("gnumberbox", "w-4", pocetDokumentuFieldOpt, pocetDokumentuFieldOptions)
                        .addField("gnumberbox", "w-4", pocetJednotekFieldOpt, pocetJednotekFieldOptions)
                        .addField("gnumberbox", "w-4", pocetListuFieldOpt, pocetListuFieldOptions));
