var Gordic;
(function (Gordic) {
    var Search;
    (function (Search) {
        /**
         * Resolver hledající balíku.
         *
         * @author TFeik
         * @date 26.08.2019
         * @since 482.1.0.456
         */
        class GBalikSearchResolver extends Gordic.Components.Search.GBaseSearchResolver {
            constructor() {
                super(...arguments);
                this.fuzzySearch = new Gordic.Utils.GObjectFuzzySearch({
                    keys: [
                        {
                            key: "ixs_zup" /* Spi.Interface.GSpiUniversalListDtoNames.ixs_zup */,
                            weight: 1
                        }
                    ]
                });
            }
            /**
             * Zde vracíme identifikátor resolveru.
             */
            getDefaultId() {
                return 'BalikSearchResolverId';
            }
            /**
             * Zde vracíme informace o doméně resolveru.
             */
            getDefaultDomain() {
                return {
                    id: 'BalikSearchResolverDomainId',
                    name: 'jres:26285020', //RC 26285020 : Balík
                    description: 'jres:32130147', //RC 32130147 : Najít balík podle identifikátoru.
                    terms: 'jres:32130219' //RC 32130219 : Balík, IxsZup, ixs zup
                };
            }
            /**
             * Zde na základě vstupního textu nabízíme výsledky hledání.
             *
             * @param {any} input
             * @param {any} task
             */
            getResult(input, task) {
                const result = [];
                // Otrimuji text a převedu na upperCase aby uživatel nemusel zadávat pid pouze velkýmy písmeny.
                const inputText = input?.text?.trim().toUpperCase();
                if (task.wasCancelled() || !inputText) {
                    return result;
                }
                // 05.01.2020 - TFeik
                // Rychlokontrola zda se jedná o ixs alespoň podle počtu znaků.
                if (inputText.length != 12) {
                    return result;
                }
                // 31.01.2020 - TFeik
                // Hledání změněno na funkci HledatBaliky místo Isl.List, který některé balíky nedodledal.
                //Gordic.Isl.Balik.list({
                //    filters: {
                //        ixs_zup: inputText
                //    }
                //}).getData()
                // 05.06.2024 - TFeik
                // Přepracováno hledání - v případě vybrané spisovny (ve SPI) nenacházelo dokumentu z jiných spisoven.
                // https://phabricator.gordic.cz/T35178
                //return Spi.WebClient.GDetailBalikuHandler.HledatBaliky(
                //    {
                //        ixs_zup: inputText,
                //        // 18.04.2024 - TFeik
                //        // Pokud je k dispozici aktuální spisovna, tak hledáv přímo v ní.
                //        // V opačném případě nechávám default.
                //        oblastHledani: $.content('main')?.gpc?.ixs_spi?.trim()
                //            ? Wfl.Interface.TypOblastHledani.VeSpisovne
                //            : void 0
                //    },
                //    // 01.06.2022 - TFeik
                //    // Doplněn typ hledání.
                //    Spi.Interface.TypHledaniBaliku.hledaniDleIdentifikatoru
                //)
                //    .then((data) => {
                const hledatBaliky = (oblastHledani) => {
                    return Gordic.Spi.WebClient.GDetailBalikuHandler.HledatBaliky({
                        ixs_zup: inputText,
                        oblastHledani: oblastHledani
                    }, 4 /* Spi.Interface.TypHledaniBaliku.hledaniDleIdentifikatoru */);
                };
                return $.when(hledatBaliky(), 
                // Hledání ve spisovně, pokud je k dispozici.
                $.content('main')?.gpc?.ixs_spi?.trim()
                    ? hledatBaliky(1 /* Wfl.Interface.TypOblastHledani.VeSpisovne */)
                    : $.Deferred().resolve().promise())
                    .then((data1, data2) => {
                    const data = [];
                    if (data1 && data1.length > 0) {
                        $.merge(data, data1);
                    }
                    if (data2 && data2.length > 0) {
                        const dataIxpZups = data.map(i => i.ixs_zup);
                        $.merge(data, data2.filter(i => !dataIxpZups.includes(i.ixs_zup)));
                    }
                    if (!data || data.length <= 0) {
                        return result;
                    }
                    // Ve chvíli, kdy byl pid nalezen a jedná se o balík
                    const balikIconTemplate = Gordic.Gin.Globals.Icons.Balik();
                    for (let i = 0, count = data.length; i < count; i++) {
                        const balik = data[i];
                        const ixsZup = balik?.ixs_zup;
                        if (!ixsZup?.trim()) {
                            continue;
                        }
                        // Vytvořím akci pro otevření detailu balíku.
                        result.push({
                            domainId: this.domain.id,
                            // 07.05.2020 - TFeik
                            // Preakce způsobuje, že se hodnota search políčka nevymaže, proto ji zatím vyhodím.
                            defaultAction: new GAction($.extend(Gordic.Prefabs.Icons.IconToActionParams(Gordic.Gin.Globals.Icons.DetailBaliku()), {
                                name: 'otevritDetailBaliku',
                                caption: 'jres:32130148', //RC 32130148 : Otevřít balík
                                run: (event, data) => {
                                    Gordic.Spi.Dialogs.GDetailBalikuDlg(undefined, {
                                        IxsZup: ixsZup
                                    }, Gordic.Global.Enums.ModOtevreni.navigateTask);
                                }
                            })),
                            //defaultAction: new GAction(Spi.PreActions.OtevriDetailBaliku({
                            //    inputData: {
                            //        parentContent: Gordic.Gin.Globals.Dialogs.ZkontrolujContent() as GContent,
                            //        ModOtevreni: Gordic.Global.Enums.ModOtevreni.navigateTask,
                            //        opt: {
                            //            IxsZup: ixsZup
                            //        }
                            //    },
                            //    actionParams: {
                            //        caption: 'jres:32130148',  //RC 32130148 : Otevřít balík
                            //    }
                            //})),
                            confidence: this.fuzzySearch.onObject(inputText, balik)[0]?.confidence ?? 0,
                            name: balikIconTemplate.text,
                            icon: balikIconTemplate.icon,
                            description: ixsZup
                        });
                    }
                    return result;
                });
            }
        }
        Search.GBalikSearchResolver = GBalikSearchResolver;
    })(Search = Gordic.Search || (Gordic.Search = {}));
})(Gordic || (Gordic = {}));
